        children.push({type:'rect',x,y:h*.84,w:w*.42,h:h*.13,fill:true,fillColor:'#e2e8f0',strokeOn:false,editorOnly});
        children.push({...text(label,x,h*.84,w*.42,h*.13,10.5),editorOnly});
