// Own one stored dataset. Manual source pulses or Live source publications copy incoming rows.
({
  apiVersion:2,
  datasetOwner:'data',
  settings:{updateMode:{type:'string',default:'Manual',options:['Manual','Live'],label:'Source update mode'},allowReaderImport:{type:'boolean',default:false,label:'Allow file import and reload'},allowReaderUpdates:{type:'boolean',default:false,label:'Allow source updates in HTML export'}},
  inputs:{data:{type:'table'},source:{type:'table',optional:true},replace:{role:'control',type:'boolean',default:false},append:{role:'control',type:'boolean',default:false},reload:{role:'control',type:'boolean',default:false}},
  dataActions(state){return {reload:{type:'reloadDataset',input:'data',trigger:'reload'},replace:{type:'replaceTable',input:'data',source:'source',trigger:'replace'},append:{type:'appendTable',input:'data',source:'source',trigger:'append'},live:{type:'syncTable',input:'data',source:'source',enabled:state.updateMode==='Live'}};},
  outputs:{data:{type:'table'},rowCount:{type:'number'}},
  initState(){return {updateMode:'Manual',allowReaderImport:false,allowReaderUpdates:false};},
  initStyle(){return {w:300,h:150,fontSize:16,fill:true,fillColor:'#ffffff',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1};},
  compute(inputs,state,context={}){
    const table=context.tables?.data;
    if(!inputs.data || typeof inputs.data.datasetId!=='string' || !/^[A-Za-z0-9_-]{1,100}$/.test(inputs.data.datasetId) || Object.hasOwn(inputs.data,'rows') || !table || !Number.isInteger(table.rowCount) || table.rowCount<0)throw new Error('Choose an owned dataset in Edit');
    return {data:inputs.data,rowCount:table.rowCount};
  },
  _text(value,x,y,w,h,size,style,color=style.textColor||'#334155',weight=400){
    const units=char=>/[MWmw@#%]/.test(char)||char.codePointAt(0)>255?1.1:/[A-Z]/.test(char)?.88:.72;
    const chars=Array.from(String(value).replace(/\s+/g,' '));let text='',used=0;
    for(let i=0;i<chars.length;i++){
      const next=units(chars[i]),remaining=i<chars.length-1?1.1:0;
      if((used+next+remaining)*size>w){text+='…';break;}
      text+=chars[i];used+=next;
    }
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font:weight+' '+size+'px sans-serif',color,strokeOn:false};
  },
  children(state,style,w,h,editing,io={}){
    const scale=Math.min(w/300,h/150),pad=12*scale,table=io.tables?.inputs?.data;
    const available=!io.error && table && Number.isInteger(io.outputs?.rowCount),text=(v,x,y,ww,hh,size,color,weight)=>this._text(v,x,y,ww,hh,size*scale,style,color,weight);
    const children=[
      {type:'rect',x:0,y:0,w,h,fill:style.fill,fillColor:style.fillColor,strokeOn:style.strokeOn,color:style.color,size:style.size,dash:style.dash},
      text(io.name?.trim()||'Dataset',pad,pad,w-pad*2,22*scale,16,undefined,600)
    ];
    if(!available){children.push(text(io.error||'Choose an owned dataset in Edit',pad,h*.48,w-pad*2,22*scale,12,'#92400e'));return children;}
    const count=io.outputs.rowCount,columnCount=table.columns.length;
    children.push(text('Owns: '+(table.name||'Stored data'),pad,43*scale,w-pad*2,20*scale,13));
    children.push(text(count+' '+(count===1?'row':'rows')+' · '+columnCount+' '+(columnCount===1?'column':'columns'),pad,72*scale,w-pad*2,25*scale,18,undefined,600));
    if(state.allowReaderImport===true){
      children.push({type:'rect',x:pad,y:h-40*scale,w:w-pad*2,h:28*scale,fill:true,fillColor:'#eef2ff',strokeOn:true,color:'#818cf8',size:1});
      children.push(text('Load data…',pad+10*scale,h-35*scale,w-pad*2-20*scale,20*scale,13,'#3730a3',600));
    }else{
      const incoming=io.tables?.inputs?.source;
      children.push(text(incoming?(state.updateMode==='Live'?'Live: ':'Incoming: ')+incoming.rowCount+' rows':table.columns.map(column=>column.name).join(' · '),pad,h-30*scale,w-pad*2,18*scale,11,'#64748b'));
    }
    return children;
  },
  handles(state,w,h){return state.allowReaderImport===true?[{id:'loadData',kind:'action',x:w/2,y:h-26*Math.min(w/300,h/150),action:{type:'importDataset',input:'data'}}]:[];},
  hitEdit(state,x,y,w,h){const scale=Math.min(w/300,h/150);return state.allowReaderImport===true && x>=12*scale && x<=w-12*scale && y>=h-40*scale && y<=h-12*scale?'loadData':null;},
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,{...io,error:io.error||'Input unavailable'});}
})

// Filters retain references to original dataset rows; they never copy rows into saved state.
// A blank column passes all rows. Comparison values use the selected column's declared type.
({
  apiVersion:2,
  _number(value){return !Number.isFinite(value)?'—':Number.isSafeInteger(value)?String(value):String(Number(value.toPrecision(8)));},
  settings:{caseSensitive:{type:'boolean',default:false,label:'Case-sensitive text'}},
  inputs:{data:{type:'table'},column:{role:'control',type:'string',default:'',columnOf:'data'},operation:{role:'control',type:'string',default:'contains',options:['contains','=','≠','>','≥','<','≤','is empty','is not empty']},text:{role:'control',type:'string',default:''},number:{role:'control',type:'number',default:0},boolean:{role:'control',type:'boolean',default:true}},
  outputs:{data:{type:'table'},rowCount:{type:'number'}},
  initState(){return {caseSensitive:false};},
  initStyle(){return {w:320,h:150,fontSize:16,fill:true,fillColor:'#ffffff',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1};},
  compute(inputs,state,context={}){
    const table=context.tables?.data;
    if(!inputs.data || typeof inputs.data.datasetId!=='string' || !table || !Array.isArray(table.columns) || !Array.isArray(table.rows) || !Array.isArray(table.rowIndices) || table.rows.length!==table.rowIndices.length || table.rowCount!==table.rows.length)throw new Error('Filter requires a complete table input');
    if(typeof inputs.column!=='string')throw new Error('Column must be a column key');
    if(inputs.column==='')return {data:inputs.data,rowCount:table.rowCount};
    const index=table.columns.findIndex(column=>column.key===inputs.column);
    if(index<0)throw new Error('Unknown filter column: '+inputs.column);
    const type=table.columns[index].type,operation=inputs.operation;
    if(!['string','number','boolean'].includes(type))throw new Error('Unsupported column type');
    if(!['contains','=','≠','>','≥','<','≤','is empty','is not empty'].includes(operation))throw new Error('Unsupported filter operation');
    if(operation==='contains' && type!=='string')throw new Error('Contains requires a text column');
    if(['>','≥','<','≤'].includes(operation) && type!=='number')throw new Error('Ordered comparisons require a numeric column');
    const fold=value=>type==='string' && state.caseSensitive!==true?value.toLowerCase():value;
    const target=type==='string'?inputs.text:type==='number'?inputs.number:inputs.boolean;
    if(!['is empty','is not empty'].includes(operation) && (typeof target!==type || type==='number' && !Number.isFinite(target)))throw new Error('Filter value must match the selected column type');
    const rows=[];
    for(let r=0;r<table.rows.length;r++){
      const value=table.rows[r][index],empty=value===null || value==='';
      let match=false;
      if(operation==='is empty')match=empty;
      else if(operation==='is not empty')match=!empty;
      else if(value!==null){
        if(typeof value!==type || type==='number' && !Number.isFinite(value))throw new Error('Cell does not match its column type');
        const a=fold(value),b=fold(target);
        switch(operation){
          case 'contains':match=a.includes(b);break;
          case '=':match=a===b;break;
          case '≠':match=a!==b;break;
          case '>':match=a>b;break;
          case '≥':match=a>=b;break;
          case '<':match=a<b;break;
          case '≤':match=a<=b;break;
        }
      }
      if(match)rows.push(table.rowIndices[r]);
    }
    return {data:{datasetId:inputs.data.datasetId,rows},rowCount:rows.length};
  },
  _text(value,x,y,w,h,size,style,color=style.textColor||'#334155',weight=400){
    const units=char=>/[MWmw@#%]/.test(char)||char.codePointAt(0)>255?1.1:/[A-Z]/.test(char)?.88:.72;
    const chars=Array.from(String(value).replace(/\s+/g,' '));let text='',used=0;
    for(let i=0;i<chars.length;i++){
      const next=units(chars[i]),remaining=i<chars.length-1?1.1:0;
      if((used+next+remaining)*size>w){text+='…';break;}
      text+=chars[i];used+=next;
    }
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font:weight+' '+size+'px sans-serif',color,strokeOn:false};
  },
  children(state,style,w,h,editing,io={}){
    const scale=Math.min(w/320,h/150),pad=12*scale,table=io.tables?.inputs?.data,inputs=io.inputs||{};
    const available=!io.error && table && Number.isInteger(io.outputs?.rowCount),text=(v,x,y,ww,hh,size,color,weight)=>this._text(v,x,y,ww,hh,size*scale,style,color,weight);
    const children=[
      {type:'rect',x:0,y:0,w,h,fill:style.fill,fillColor:style.fillColor,strokeOn:style.strokeOn,color:style.color,size:style.size,dash:style.dash},
      text(io.name?.trim()||'Table filter',pad,pad,w-pad*2,22*scale,16,undefined,600)
    ];
    if(!available){children.push(text(io.error||'Connect a table in Edit',pad,h*.43,w-pad*2,22*scale,12,'#92400e'));return children;}
    const column=table.columns.find(column=>column.key===inputs.column),target=column?.type==='number'?inputs.number:column?.type==='boolean'?inputs.boolean:inputs.text;
    const condition=column?column.name+' '+inputs.operation+(['is empty','is not empty'].includes(inputs.operation)?'':' '+(typeof target==='string'?'“'+target+'”':typeof target==='number'?this._number(target):target)):'All rows';
    children.push(text(condition,pad,47*scale,w-pad*2,24*scale,14));
    children.push(text(io.outputs.rowCount+' of '+table.rowCount+' rows',pad,84*scale,w-pad*2,26*scale,20,undefined,600));
    if(column?.type==='string' && state.caseSensitive!==true && !['is empty','is not empty'].includes(inputs.operation))children.push(text('Ignoring letter case',pad,h-26*scale,w-pad*2,16*scale,10,'#64748b'));
    return children;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,{...io,error:io.error||'Input unavailable'});}
})

// Each accepted entry queues its value and one submitted pulse, including unchanged entries.
// The bounded inbox survives Pause; a fresh runtime retains the latest value without replaying it.
// A 10 ms arming gap lets connected Clear signals settle before the first queued pulse.
({
  apiVersion:2,
  wakePolicy:'latest',
  settings:{maxLength:{type:'number',default:2000,min:1,max:2000,step:1,label:'Maximum length'},required:{type:'boolean',default:false,label:'Required'},placeholder:{type:'string',default:'',label:'Placeholder'},showSubmitted:{type:'boolean',default:false,label:'Show submission state'},showHints:{type:'boolean',default:false,label:'Show hints'}},
  inputs:{clear:{role:'control',type:'boolean',default:false}},
  outputs:{value:{type:'string'},submitted:{role:'control',type:'boolean'}},
  initState(){return {values:[''],current:0,pending:[],submitted:false,press:0,entryRuntime:'',showSubmitted:false,showHints:false,maxLength:2000,required:false,placeholder:''};},
  initStyle(){return {w:320,h:72,fontSize:18,fill:true,fillColor:'#ffffff',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1.5};},
  _value(value){if(typeof value!=='string' || value.length>2000)throw new Error('Text must contain at most 2000 characters'); return value;},
  _config(state){if(!Number.isSafeInteger(state.maxLength) || state.maxLength<1 || state.maxLength>2000 || typeof state.required!=='boolean' || typeof state.placeholder!=='string' || state.placeholder.length>120 || /[\r\n]/.test(state.placeholder))throw new Error('Choose a length from 1 to 2000 and a single-line placeholder of at most 120 characters');},
  _state(state){
    this._config(state);
    if(!Array.isArray(state.values) || !state.values.length || state.values.length>65 ||
       !Number.isSafeInteger(state.current) || state.current<0 || state.current>=state.values.length ||
       !Array.isArray(state.pending) || state.pending.length>64 ||
       state.pending.some(index=>!Number.isSafeInteger(index) || index<0 || index>=state.values.length) ||
       typeof state.submitted!=='boolean' || !Number.isSafeInteger(state.press) || state.press<0 ||
       (state.entryRuntime!==undefined && (typeof state.entryRuntime!=='string' || state.entryRuntime.length>128)))throw new Error('Invalid stored input state');
    state.values.forEach(value=>this._value(value));
    if(JSON.stringify(state.values).length>3200 || JSON.stringify(state).length>4000)throw new Error('Stored input text is too large');
  },
  _latest(state){return state.values[state.pending.length?state.pending[state.pending.length-1]:state.current];},
  _compact(state){
    const used=[...new Set([state.current,...state.pending])],values=used.map(index=>state.values[index]);
    return {...state,values,current:used.indexOf(state.current),pending:state.pending.map(index=>used.indexOf(index))};
  },
  _entry(value,state){
    this._value(value);if(value.length>state.maxLength)throw new Error('Text exceeds the configured maximum length');
    if(state.required && !value.trim())throw new Error('Enter a value');
    if(/[\r\n]/.test(value))throw new Error('Enter a single line of text');
    return value;
  },
  publish(state){
    this._state(state);
    return {value:state.submitted?state.values[state.current]:this._latest(state),submitted:state.submitted};
  },
  compute(inputs,state){return this.publish(state);},
  transition(inputs,state,memory,context){
    this._state(state);
    const now=context.now,clear=inputs.clear===undefined?false:inputs.clear;
    if(typeof clear!=='boolean')throw new Error('Clear trigger must be Boolean');
    if(!Number.isFinite(now) || now<0)throw new Error('Input requires a valid monotonic time');
    if(memory?.primed!==true){
      const runtimeId=typeof context.runtimeId==='string'?context.runtimeId:'';
      if(!runtimeId || state.entryRuntime!==runtimeId){
        return {state:{...state,values:[this._latest(state)],current:0,pending:[],submitted:false,entryRuntime:runtimeId},
          memory:{primed:true,phase:'idle',nextAt:null,clear},nextWakeAt:null};
      }
      // A first entry accepted while paused belongs to this runtime, so Step may emit it.
      state={...state,submitted:false};memory={primed:true,phase:'idle',nextAt:null,clear};
