    for(const [k,src] of Object.entries(state.cells||{})){
      const pos=parse(k);if(!pos)continue;
      const n=axis==='c'?move(pos.c):move(pos.r);
      if(n===null)continue;   // the deleted column/row's own cells
      cells[axis==='c'?this._key(n,pos.r):this._key(pos.c,n)]=rewrite(src);
    }
    const next={...state,cells,cols:dims.cols+(axis==='c'?delta:0),rows:dims.rows+(axis==='r'?delta:0)};
    for(const prop of ['formats','aligns']){   // per-cell settings move with their cells
      if(!state[prop])continue;
      const out={};
      for(const [k,v] of Object.entries(state[prop])){
        const pos=parse(k);if(!pos)continue;
        const n=axis==='c'?move(pos.c):move(pos.r);
        if(n!==null)out[axis==='c'?this._key(n,pos.r):this._key(pos.c,n)]=v;
      }
      if(Object.keys(out).length)next[prop]=out;else delete next[prop];
    }
    if(axis==='c'&&Array.isArray(state.weights)){
      const wt=dims.weights.slice();
      if(delta>0)wt.splice(at,0,wt[Math.max(0,at-1)]);else wt.splice(at,1);
      if(wt.every(x=>x===1))delete next.weights;else next.weights=wt;
    }
    return next;
  },
  dragEdit(state,handle,value,ly,w,h){
    const dims=this._dims(state),op=/^([cr])(ins|del)(\d+)$/.exec(handle);
    if(op){
      const axis=op[1],add=op[2]==='ins',i=+op[3],count=axis==='c'?dims.cols:dims.rows;
      if(i>(add?count:count-1) || (!add && count<=1) || (add && !this._fits(dims.cols+(axis==='c'),dims.rows+(axis==='r'))))return {state};
      const next=this._restructure(state,axis,i,add?1:-1);
      if(next===state||JSON.stringify(next).length>3900)return {state};   // keep within the 4,000-character state limit
      const L=this._layout(w,h,dims),colPx=add?L.ws[Math.max(0,i-1)]:L.ws[i];
      return {state:next,size:axis==='c'?{w:w+(add?colPx:-colPx)}:{h:h+(add?L.rh:-L.rh)}};
    }
    const width=/^(cw|cwreset|colw)(\d+)$/.exec(handle);
    if(width){   // column width: the shape grows/shrinks by the difference, other columns keep theirs
      const c=+width[2];
      if(c>=dims.cols||width[1]==='colw')return {state};   // colw: only opens the width entry
      const L=this._layout(w,h,dims),px=width[1]==='cw'?Math.max(8,Math.min(2000,Number(value))):L.unit;
      if(!Number.isFinite(px))return {state};
      const wt=dims.weights.slice();wt[c]=width[1]==='cw'?px/L.unit:1;
      const next={...state};
      if(wt.every(x=>x===1))delete next.weights;else next.weights=wt.map(x=>Math.round(x*1e4)/1e4);
      return {state:next,size:{w:w-L.ws[c]+px}};
    }
    const fn=/^fn:([A-Z]+):([A-Z]\d+)$/.exec(handle);
    if(fn){   // "Insert function" from the context menu
      const [,name,k]=fn,c=this._COLS.indexOf(k[0]),r=+k.slice(1)-1;
      if(this._reserved(state,c,r)||!this._fnArgs(name)||c<0||c>=dims.cols||r<0||r>=dims.rows)return {state};
      const next={...state,cells:{...(state.cells||{}),[k]:this._fnInsert((state.cells||{})[k],name).text}};
      return {state:JSON.stringify(next).length>3900?state:next};
    }
    const look=/^(?:nf(\d+)|al:(left|center|right|default)):([A-Z]\d+)$/.exec(handle);
    if(look){   // "Number format" / "Alignment" from the context menu
      const [,fi,al,k]=look,c=this._COLS.indexOf(k[0]),r=+k.slice(1)-1;
      if(c<0||c>=dims.cols||r<0||r>=dims.rows)return {state};
      const prop=fi!==undefined?'formats':'aligns';
      const v=fi!==undefined?(this._FORMATS[+fi]||[''])[0]:al==='default'?'':al;
      const map={...(state[prop]||{})};
      if(v)map[k]=v;else delete map[k];
      const next={...state};
      if(Object.keys(map).length)next[prop]=map;else delete next[prop];
      return {state:JSON.stringify(next).length>3900?state:next};
    }
    const cell=/^([A-Z])(\d+)$/.exec(handle);
    if(!cell||this._reserved(state,this._COLS.indexOf(cell[1]),+cell[2]-1)||this._COLS.indexOf(cell[1])>=dims.cols||+cell[2]<1||+cell[2]>dims.rows||typeof value!=='string')return {state};
    const cells={...(state.cells||{})},text=value[0]==="'"?value:value.trim();
    if(text)cells[handle]=text;else delete cells[handle];
    const next={...state,cells};
    return {state:JSON.stringify(next).length>3900?state:next};   // keep within the 4,000-character state limit
  }
})

// A numeric display and pass-through. Connect value through Edit before use.
({
  apiVersion:2,
  inputs:{value:{type:'number'}},
  outputs:{value:{type:'number'}},
  initState(){return {};},
  initStyle(){return {w:220,h:100,fontSize:24,strokeOn:false};},
  compute(inputs){return {value:inputs.value};},
  _number(value){return !Number.isFinite(value)?'—':Number.isSafeInteger(value)?String(value):String(Number(value.toPrecision(8)));},
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  children(state,style,w,h,editing,io){
    const caption=this._caption(io.name,'Value label',w,h*.36,style);
    return [
    {type:'rect',x:0,y:0,w,h,fill:style.fill,fillColor:style.fillColor,strokeOn:style.strokeOn,color:style.color,size:style.size},
    {type:'text',x:0,y:0,w,h:h*.36,...caption,align:'center',color:style.textColor,strokeOn:false},
    {type:'text',x:0,y:h*.38,w,h:h*.56,text:this._number(io.outputs.value),align:'center',font:style.font,color:style.textColor,strokeOn:false}
  ];}
})

// A boolean display. Missing inputs remain unavailable; they never look like false.
({
  apiVersion:2,
  inputs:{value:{type:'boolean'}},
  outputs:{value:{type:'boolean'}},
  initState(){return {};},
  initStyle(){return {w:220,h:100,fontSize:22,strokeOn:false};},
  compute(inputs){return {value:inputs.value};},
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  children(state,style,w,h,editing,io){
    const value=io.outputs.value,diameter=Math.min(w*.18,h*.42);
    const caption=this._caption(io.name,'Status indicator',w,h*.33,style);
    return [
      {type:'rect',x:0,y:0,w,h,fill:style.fill,fillColor:style.fillColor,strokeOn:style.strokeOn,color:style.color,size:style.size},
      {type:'text',x:0,y:0,w,h:h*.33,...caption,align:'center',color:style.textColor,strokeOn:false},
      {type:'ellipse',x:w*.18-diameter/2,y:h*.66-diameter/2,w:diameter,h:diameter,fill:true,fillColor:value?'#15803d':'#64748b',strokeOn:false},
      {type:'text',x:w*.32,y:h*.36,w:w*.65,h:h*.60,text:value?'ON':'OFF',align:'center',font:style.font,color:style.textColor,strokeOn:false}
    ];
  }
})

// A string display and pass-through. The canvas shows a wrapped preview; value stays complete.
({
  apiVersion:2,
  settings:{showName:{type:'boolean',default:false,label:'Show name'},showHints:{type:'boolean',default:false,label:'Show hints'}},
  inputs:{value:{type:'string',default:''}},
  outputs:{value:{type:'string'}},
  initState(){return {showName:false,showHints:false};},
  initStyle(){return {w:280,h:64,fontSize:18,fill:false,fillColor:'#ffffff',strokeOn:false,color:'#64748b',textColor:'#334155',size:2};},
  compute(inputs){
    if(typeof inputs.value!=='string' || inputs.value.length>2000)throw new Error('Text label requires a string of at most 2000 characters');
    return {value:inputs.value};
  },
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  _view(text,width,height,size){
    const unit=c=>/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72;
    const room=Math.max(1,width)/size,rows=[];
    for(const block of text.replace(/\r\n?/g,'\n').replace(/\t/g,'    ').split('\n')){
      let chars=Array.from(block);
      if(!chars.length)rows.push('');
      while(chars.length){
        let length=0,used=0,space=0;
        for(const c of chars){if(length && used+unit(c)>room)break;used+=unit(c);length++;if(/\s/.test(c))space=length;}
        if(length<chars.length && space>0)length=space;
        rows.push(chars.splice(0,length).join(''));
      }
    }
    const lineHeight=size*1.35,limit=Math.max(1,Math.min(80,Math.floor(height/lineHeight))),hidden=rows.length>limit;
    return {lines:rows.slice(0,limit),lineHeight,hidden};
  },
  children(state,style,w,h,editing,io={}){
    const available=!io.error && typeof io.outputs?.value==='string',value=available?io.outputs.value:'';
    const boxed=style.strokeOn===true || style.fill===true,stroke=style.strokeOn===true?Math.max(0,style.size||0):0;
    const inset=boxed?Math.min(4+stroke/2,w/4,h/4):0,width=Math.max(1,w-inset*2),height=Math.max(1,h-inset*2);
    const size=Math.max(5,Math.min(style.fontSize||18,height)),caption=state.showName===true?Math.min(22,height*.35):0;
    const hintNeeded=state.showHints===true && available && (value==='' || this._view(value,width,Math.max(1,height-caption),size).hidden);
    const footer=hintNeeded?Math.min(14,height*.25):0,bodyHeight=Math.max(1,height-caption-footer),bodySize=Math.min(size,bodyHeight/1.35);
    const font=(fontSize,weight=400)=>(style.font||weight+' '+fontSize+'px sans-serif').replace(/\d+(?:\.\d+)?px/,fontSize+'px');
    const text=(value,x,y,width,height,fontSize,color=style.textColor||'#334155')=>({type:'text',x,y,w:width,h:height,text:value,plainText:true,align:'left',font:font(fontSize),color,strokeOn:false});
    const children=[];
    if(boxed)children.push({type:'rect',x:0,y:0,w,h,strokeOn:style.strokeOn===true,color:style.color,size:style.size,dash:style.dash,fill:style.fill===true,fillColor:style.fillColor});
    if(caption)children.push({...text('',inset,inset,width,caption,12),...this._caption(io.name,'Text label',width,caption,{...style,fontSize:12})});
    let status='';
    if(!available)children.push(text('Input unavailable',inset,inset+caption,width,Math.min(bodyHeight,size*1.35),Math.min(size,bodyHeight/1.35),'#92400e'));
    else if(value===''){
      status='Empty text';
    }else{
      const view=this._view(value,width,bodyHeight,bodySize);
      view.lines.forEach((line,index)=>children.push(text(line,inset,inset+caption+index*view.lineHeight,width,view.lineHeight,bodySize)));
      if(view.hidden)status='More text in output…';
    }
    if(footer && status)children.push(text(status,inset,inset+height-footer,width,footer,Math.min(10,footer/1.35),'#64748b'));
    return children;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,{...io,error:io.error||'Input unavailable'});}
})

